import{G as e,W as t,ct as n,it as r,n as i,q as a}from"./chunks/framework.2K1covnI.js";var o=JSON.parse(`{"title":"当前架构","description":"","frontmatter":{},"headers":[],"relativePath":"architecture.md","filePath":"architecture.md","lastUpdated":1790057781000}`),s={name:`architecture.md`};function c(i,o,s,c,l,u){let d=n(`MermaidDiagram`);return r(),t(`div`,null,[o[0]||=e(`<h1 id="当前架构" tabindex="-1">当前架构 <a class="header-anchor" href="#当前架构" aria-label="Permalink to “当前架构”">​</a></h1><h2 id="目标与边界" tabindex="-1">目标与边界 <a class="header-anchor" href="#目标与边界" aria-label="Permalink to “目标与边界”">​</a></h2><p>本站是由 VitePress 构建并部署到 GitHub Pages 的静态知识站。文章、投资记录和项目介绍都是 Markdown 文件；构建阶段负责扫描和组织内容，浏览器端只消费已经注入主题的数据，不直接读取文件系统。</p><h2 id="内容数据流" tabindex="-1">内容数据流 <a class="header-anchor" href="#内容数据流" aria-label="Permalink to “内容数据流”">​</a></h2>`,4),a(d,{source:`Zmxvd2NoYXJ0IExSCiAgICBBW2RvY3Mg5LiL55qEIE1hcmtkb3duXSAtLT4gQltjb3JlL2NvbnRlbnQvZW50cmllcy50c10KICAgIEIgLS0+IENbcG9zdHMgLyBpbnZlc3QgLyBwcm9qZWN0cyDpoobln58gQVBJXQogICAgQyAtLT4gRFsudml0ZXByZXNzL2NvbmZpZy50c10KICAgIEQgLS0+IEVbdGhlbWVDb25maWddCiAgICBFIC0tPiBGW1Z1ZSDkuLvpopjmqKHlnZfkuI7pobXpnaJdCg==`}),o[1]||=e(`<p><code>docs/.vitepress/theme/core/content/entries.ts</code> 是扫描 Markdown、解析 frontmatter、归一化日期、获取更新时间和生成路由的唯一实现。<code>modules/post</code>、<code>modules/invest</code> 和 <code>modules/projects</code> 只配置各自目录及过滤条件，再由 <code>docs/.vitepress/config.ts</code> 将结果注入 <code>themeConfig</code>。</p><h2 id="主题边界" tabindex="-1">主题边界 <a class="header-anchor" href="#主题边界" aria-label="Permalink to “主题边界”">​</a></h2><ul><li><code>theme/core/</code>：跨内容域的数据类型、扫描、日期和路径规则。</li><li><code>theme/modules/</code>：按业务域组织组件、视图、常量和领域适配器；模块不自行扫描文件系统。</li><li><code>theme/shared/</code>：布局、通用效果和跨模块 composable。</li><li><code>theme/index.ts</code>：组合默认主题、注册 Pinia 以及可在 Markdown 中使用的全局组件。</li><li><code>theme/styles/tokens.css</code>：运行时设计 token；规范值与使用原则由根目录 <code>DESIGN.md</code> 定义。</li><li><code>theme/styles/base.css</code>：页面基础样式和跨页面内容模式。</li><li><code>theme/styles/vitepress.css</code>：对 VitePress 默认主题类名和变量的定向覆盖。</li><li><code>theme/index.ts</code>：按 token、基础样式、VitePress 覆盖的顺序加载全局 CSS。</li></ul><h2 id="运行时与外部服务" tabindex="-1">运行时与外部服务 <a class="header-anchor" href="#运行时与外部服务" aria-label="Permalink to “运行时与外部服务”">​</a></h2><p>内容索引在 Node 构建阶段生成。浏览器端负责页面交互、主题切换、评论数加载和 giscus 评论渲染。评论配置位于 <code>theme/modules/comment/</code>，敏感标识通过 <code>VITE_GISCUS_*</code> 环境变量或 GitHub Secrets 注入。</p><h2 id="部署" tabindex="-1">部署 <a class="header-anchor" href="#部署" aria-label="Permalink to “部署”">​</a></h2><p><code>.github/workflows/deploy-pages.yml</code> 在 <code>master</code> 更新后使用 pnpm 构建，将 <code>docs/.vitepress/dist</code> 发布到 <code>gh-pages</code>。构建产物不是源码，不在仓库主分支维护。</p><h2 id="不变量" tabindex="-1">不变量 <a class="header-anchor" href="#不变量" aria-label="Permalink to “不变量”">​</a></h2><ul><li>内容文件继续位于 <code>docs/posts/</code>、<code>docs/invest/</code> 和 <code>docs/projects/</code>。</li><li>内容扫描、时间与路由规则只在 <code>core/content/entries.ts</code> 实现一次。</li><li>页面组件通过 <code>themeConfig</code> 或模块封装读取内容，不直接访问文件系统。</li><li>视觉规则以 <code>DESIGN.md</code> 为规范源，CSS 变量是其运行时映射。</li><li>行为变化由 <code>openspec/</code> 管理；本文件只描述已经落地的当前结构。</li></ul>`,9)])}var l=i(s,[[`render`,c]]);export{o as __pageData,l as default};